with

sq_stg_order_items as (
    -- SQ_STG_ORDER_ITEMS (Source Qualifier): reads STG_ORDER_ITEMS
    select
        cast(order_item_id as varchar) as order_item_id,
        cast(order_id as varchar) as order_id,
        cast(product_id as varchar) as product_id
    from {{ ref('stg_order_items') }}
),

sq_stg_orders as (
    -- SQ_STG_ORDERS (Source Qualifier): reads STG_ORDERS
    select
        cast(order_id as varchar) as order_id,
        cast(customer_id as varchar) as customer_id,
        cast(location_id as varchar) as location_id,
        cast(ordered_at_day as timestamp) as ordered_at_day,
        cast(subtotal_cents as double) as subtotal_cents,
        cast(tax_paid_cents as double) as tax_paid_cents,
        cast(order_total_cents as decimal(12, 2)) as order_total_cents,
        cast(subtotal as decimal(12, 2)) as subtotal,
        cast(tax_paid as decimal(12, 2)) as tax_paid,
        cast(order_total as decimal(12, 2)) as order_total
    from {{ ref('stg_orders') }}
),

jnr_items_orders as (
    -- JNR_ITEMS_ORDERS (Joiner, Normal Join): ORDER_ID = ORDER_ID1
    select
        master.order_item_id as order_item_id,
        master.order_id as order_id,
        master.product_id as product_id,
        detail.customer_id as customer_id,
        detail.location_id as location_id,
        detail.ordered_at_day as ordered_at_day
    from sq_stg_orders as detail
    inner join sq_stg_order_items as master
        on (master.order_id = detail.order_id)
),

sq_stg_products as (
    -- SQ_STG_PRODUCTS (Source Qualifier): reads STG_PRODUCTS
    select
        cast(product_id as varchar) as product_id,
        cast(product_name as varchar) as product_name,
        cast(product_type as varchar) as product_type,
        cast(product_price_cents as double) as product_price_cents,
        cast(product_price as decimal(12, 2)) as product_price,
        cast(product_description as varchar) as product_description,
        cast(is_food_item as decimal(1, 0)) as is_food_item,
        cast(is_drink_item as decimal(1, 0)) as is_drink_item
    from {{ ref('stg_products') }}
),

jnr_add_products as (
    -- JNR_ADD_PRODUCTS (Joiner, Normal Join): PRODUCT_ID = PRODUCT_ID1
    select
        master.order_item_id as order_item_id,
        master.order_id as order_id,
        master.product_id as product_id,
        master.customer_id as customer_id,
        master.location_id as location_id,
        master.ordered_at_day as ordered_at_day,
        detail.product_name as product_name,
        detail.product_type as product_type,
        detail.product_price as product_price,
        detail.is_food_item as is_food_item,
        detail.is_drink_item as is_drink_item
    from sq_stg_products as detail
    inner join jnr_items_orders as master
        on (master.product_id = detail.product_id)
),

sq_stg_customers as (
    -- SQ_STG_CUSTOMERS (Source Qualifier): reads STG_CUSTOMERS
    select
        cast(customer_id as varchar) as customer_id,
        cast(customer_name as varchar) as customer_name
    from {{ ref('stg_customers') }}
),

jnr_add_customers as (
    -- JNR_ADD_CUSTOMERS (Joiner, Master Outer Join): CUSTOMER_ID = CUSTOMER_ID1
    select
        master.order_item_id as order_item_id,
        master.order_id as order_id,
        master.product_id as product_id,
        master.customer_id as customer_id,
        master.location_id as location_id,
        master.ordered_at_day as ordered_at_day,
        master.product_name as product_name,
        master.product_type as product_type,
        master.product_price as product_price,
        master.is_food_item as is_food_item,
        master.is_drink_item as is_drink_item,
        detail.customer_name as customer_name
    from sq_stg_customers as detail
    left join jnr_add_products as master
        on (master.customer_id = detail.customer_id)
),

sq_stg_locations as (
    -- SQ_STG_LOCATIONS (Source Qualifier): reads STG_LOCATIONS
    select
        cast(location_id as varchar) as location_id,
        cast(location_name as varchar) as location_name,
        cast(opened_date as timestamp) as opened_date,
        cast(tax_rate as decimal(6, 4)) as tax_rate,
        cast(region as varchar) as region
    from {{ ref('stg_locations') }}
),

jnr_add_locations as (
    -- JNR_ADD_LOCATIONS (Joiner, Master Outer Join): LOCATION_ID = LOCATION_ID1
    select
        master.order_item_id as order_item_id,
        master.order_id as order_id,
        master.product_id as product_id,
        master.customer_id as customer_id,
        master.location_id as location_id,
        master.ordered_at_day as ordered_at_day,
        master.product_name as product_name,
        master.product_type as product_type,
        master.product_price as product_price,
        master.is_food_item as is_food_item,
        master.is_drink_item as is_drink_item,
        master.customer_name as customer_name,
        detail.location_name as location_name,
        detail.tax_rate as tax_rate,
        detail.region as region
    from sq_stg_locations as detail
    left join jnr_add_customers as master
        on (master.location_id = detail.location_id)
),

sq_stg_supplies as (
    -- SQ_STG_SUPPLIES (Source Qualifier): reads STG_SUPPLIES
    select
        cast(supply_id as varchar) as supply_id,
        cast(supply_name as varchar) as supply_name,
        cast(supply_cost_cents as decimal(12, 2)) as supply_cost_cents,
        cast(supply_cost as decimal(12, 2)) as supply_cost,
        cast(is_perishable as decimal(1, 0)) as is_perishable,
        cast(product_id as varchar) as product_id
    from {{ ref('stg_supplies') }}
),

srt_supplies as (
    -- SRT_SUPPLIES (Sorter on product_id asc): row order only matters to order-dependent logic downstream, so no ORDER BY here
    select
        product_id as product_id,
        supply_cost as supply_cost,
        is_perishable as is_perishable
    from sq_stg_supplies
),

agg_supplies_by_product as (
    -- AGG_SUPPLIES_BY_PRODUCT (Aggregator) grouped by PRODUCT_ID
    select
        product_id as product_id,
        sum(supply_cost) as supply_cost_per_product,
        max(is_perishable) as has_perishable_supply
    from srt_supplies
    group by product_id
),

jnr_add_supplies as (
    -- JNR_ADD_SUPPLIES (Joiner, Master Outer Join): PRODUCT_ID = PRODUCT_ID1
    select
        master.order_item_id as order_item_id,
        master.order_id as order_id,
        master.product_id as product_id,
        master.customer_id as customer_id,
        master.location_id as location_id,
        master.ordered_at_day as ordered_at_day,
        master.product_name as product_name,
        master.product_type as product_type,
        master.product_price as product_price,
        master.is_food_item as is_food_item,
        master.is_drink_item as is_drink_item,
        master.customer_name as customer_name,
        master.location_name as location_name,
        master.tax_rate as tax_rate,
        master.region as region,
        detail.supply_cost_per_product as supply_cost_per_product,
        detail.has_perishable_supply as has_perishable_supply
    from agg_supplies_by_product as detail
    left join jnr_add_locations as master
        on (master.product_id = detail.product_id)
),

exp_item_calculations as (
    -- EXP_ITEM_CALCULATIONS (Expression)
    select
        order_item_id as order_item_id,
        order_id as order_id,
        product_id as product_id,
        customer_id as customer_id,
        location_id as location_id,
        ordered_at_day as ordered_at_day,
        product_name as product_name,
        product_type as product_type,
        product_price as product_price,
        is_food_item as is_food_item,
        is_drink_item as is_drink_item,
        case when (customer_name is null) then 'Unknown' else customer_name end as customer_name,
        case when (location_name is null) then 'Unknown' else location_name end as location_name,
        case when (region is null) then 'Unknown' else region end as region,
        product_price as item_revenue,
        (case when (supply_cost_per_product is null) then 0 else supply_cost_per_product end) as item_cogs,
        (product_price - (case when (supply_cost_per_product is null) then 0 else supply_cost_per_product end)) as item_gross_profit,
        (case when (product_price = 0) then 0 else ((product_price - (case when (supply_cost_per_product is null) then 0 else supply_cost_per_product end)) / product_price) end) as item_gross_margin_pct,
        (product_price * (case when (tax_rate is null) then 0 else tax_rate end)) as item_tax_estimate,
        (product_price + (product_price * (case when (tax_rate is null) then 0 else tax_rate end))) as item_total_estimate,
        (case when (has_perishable_supply is null) then 0 else has_perishable_supply end) as has_perishable_supply
    from jnr_add_supplies
)

select * from exp_item_calculations
